'use strict';
/* El Rey y Sir Gaspar con más poses (14/11, pedido del dueño: "haz las otras poses del lider de los mercenarios, y al rey
   añadele animaciones chistosas como torpes y otras poses").
   Arte de PixelLab desde sus dibujos de costado (como estilo), al doble de tamaño y achicado a su escala de píxel, en hojas de
   100×100 con los pies en la misma línea que las de costado:
   - SIR GASPAR, el señor de los mercenarios: de frente y de espaldas, quieto y caminando (8 cuadros).
   - EL REY ALDRIC: de frente y de espaldas, quieto y caminando (8 cuadros), y cuatro animaciones torpes y chistosas:
     se tropieza con la capa y casi se cae revoleando la espada; se rasca la cabeza debajo de la corona, confundido;
     bosteza estirándose con la espada en alto; y se le resbala la corona sobre los ojos y la vuelve a acomodar.
   Cómo se usan (sin tocar los archivos de cada escena): cuando el Rey o Gaspar caminan para abajo se los ve de frente y
   para arriba de espaldas; al pararse quedan mirando para donde iban (de frente si bajaban). El Rey parado (de costado)
   cada 10 a 18 s hace una de sus torpezas, si está a la vista y no hay un diálogo abierto.
   CK_REY_POSES.hacer(escena, sprite, 'torpe'|'rasca'|'bosteza'|'corona') la hace a pedido (para las escenas).
   Borrar la línea de index.html lo saca. */
(function () {
  if (typeof MainGameScene === 'undefined' || typeof Phaser === 'undefined') return;
  const P = MainGameScene.prototype;
  const ARTE = {"ck_gaspar_espalda": ["data:image/png;base64,", 1], "ck_gaspar_frente": ["data:image/png;base64,", 1], "ck_gaspar_walk_espalda": ["data:image/png;base64,", 8], "ck_gaspar_walk_frente": ["data:image/png;base64,", 8], "ck_rey_bosteza": ["data:image/png;base64,", 9], "ck_rey_corona": ["data:image/png;base64,", 9], "ck_rey_espalda": ["data:image/png;base64,", 1], "ck_rey_frente": ["data:image/png;base64,", 1], "ck_rey_rasca": ["data:image/png;base64,", 9], "ck_rey_torpe": ["data:image/png;base64,", 13], "ck_rey_walk_espalda": ["data:image/png;base64,", 8], "ck_rey_walk_frente": ["data:image/png;base64,", 8]};
  const RITMO = { ck_rey_walk_frente: [9, -1], ck_rey_walk_espalda: [9, -1], ck_rey_frente: [1, 0], ck_rey_espalda: [1, 0],
    ck_rey_torpe: [11, 0], ck_rey_rasca: [8, 0], ck_rey_bosteza: [7, 0], ck_rey_corona: [9, 0],
    ck_gaspar_walk_frente: [10, -1], ck_gaspar_walk_espalda: [10, -1], ck_gaspar_frente: [1, 0], ck_gaspar_espalda: [1, 0] };
  const IMG = {};
  Object.keys(ARTE).forEach(k => { const im = new Image(); im.src = ARTE[k][0]; IMG[k] = im; });
  const animar = S => Object.keys(ARTE).forEach(k => {
    if (!S.textures.exists(k) || S.anims.exists(k)) return;
    const [fr, rep] = RITMO[k] || [8, 0];
    S.anims.create({ key: k, frames: S.anims.generateFrameNumbers(k, { start: 0, end: ARTE[k][1] - 1 }), frameRate: fr, repeat: rep });
  });
  const texturas = S => Object.keys(IMG).forEach(k => {
    const im = IMG[k]; if (S.textures.exists(k)) return;
    const poner = () => { try { if (!S.textures.exists(k)) S.textures.addSpriteSheet(k, im, { frameWidth: 100, frameHeight: 100 }); animar(S); } catch (e) {} };
    if (im.complete && im.naturalWidth) poner(); else im.addEventListener('load', poner, { once: true });
  });
  const pre0 = P.preload;
  P.preload = function () { const r = pre0 ? pre0.apply(this, arguments) : undefined; try { texturas(this); } catch (e) {} return r; };
  const cr0 = P.create;
  P.create = function () { const r = cr0 ? cr0.apply(this, arguments) : undefined; try { texturas(this); animar(this); } catch (e) {} return r; };

  // ------------------------------------------------------------------ quién es quién
  const FAM = {
    rey: { lado: 'kingprueba_walk', quieto: 'kingprueba_idle', wf: 'ck_rey_walk_frente', we: 'ck_rey_walk_espalda', f: 'ck_rey_frente', e: 'ck_rey_espalda',
      gracias: ['ck_rey_torpe', 'ck_rey_rasca', 'ck_rey_bosteza', 'ck_rey_corona'] },
    gaspar: { lado: 'ck_gaspar_walk', quieto: 'ck_gaspar_idle', wf: 'ck_gaspar_walk_frente', we: 'ck_gaspar_walk_espalda', f: 'ck_gaspar_frente', e: 'ck_gaspar_espalda', gracias: [] }
  };
  const DE = {};
  Object.keys(FAM).forEach(n => { const F = FAM[n]; [F.lado, F.quieto, F.wf, F.we, F.f, F.e].concat(F.gracias).forEach(k => { DE[k] = F; }); });
  const MIAS = new Set(Object.keys(ARTE));

  // el juego vuelve a pedir el caminar o el quieto de costado: si ya camina de frente/espaldas, está quieto de frente o
  // haciendo una torpeza, no se corta
  const play0 = Phaser.GameObjects.Sprite.prototype.play;
  Phaser.GameObjects.Sprite.prototype.play = function (key, ignore) {
    try {
      const k = typeof key === 'string' ? key : key && key.key, F = k && DE[k];
      if (F && !this._ckRpPropio) {
        const cur = this.anims && this.anims.currentAnim && this.anims.currentAnim.key;
        if (k === F.lado && (cur === F.wf || cur === F.we)) return this;
        if (k === F.quieto && (cur === F.f || cur === F.e)) return this;
        if (k === F.quieto && F.gracias.indexOf(cur) >= 0 && this.anims.isPlaying) return this;
      }
    } catch (e) {}
    return play0.apply(this, arguments);
  };
  const tocar = (sp, k) => { if (!sp.scene || !sp.scene.anims.exists(k)) return false; sp._ckRpPropio = true; try { play0.call(sp, k, true); } finally { sp._ckRpPropio = false; } return true; };

  // ------------------------------------------------------------------ una torpeza del Rey
  const hacer = (S, sp, cual) => {
    const F = FAM.rey, k = cual ? 'ck_rey_' + cual : F.gracias[(Math.random() * F.gracias.length) | 0];
    if (!sp || !sp.active || !S.anims.exists(k)) return false;
    tocar(sp, k);
    sp.once(Phaser.Animations.Events.ANIMATION_COMPLETE, () => { if (sp.active && sp.anims.currentAnim && sp.anims.currentAnim.key === k) tocar(sp, F.quieto); });
    try { if (k === 'ck_rey_torpe') sfx.fx('ck_ropa', 0.4, { rate: 0.9 }); else if (k === 'ck_rey_bosteza') sfx.fx('ui_hover', 0.15, { rate: 0.5 }); } catch (e) {}
    return true;
  };

  // ------------------------------------------------------------------ cada cuadro: hacia dónde va y qué hace
  const mirar = S => {
    const now = S.time.now, vista = S.cameras.main.worldView;
    S.children.list.forEach(sp => {
      if (sp.type !== 'Sprite' || !sp.active || !sp.anims || !sp.anims.currentAnim) return;
      const k = sp.anims.currentAnim.key, F = DE[k]; if (!F) return;
      const dx = sp.x - (sp._ckRpX === undefined ? sp.x : sp._ckRpX), dy = sp.y - (sp._ckRpY === undefined ? sp.y : sp._ckRpY);
      sp._ckRpX = sp.x; sp._ckRpY = sp.y;
      sp._ckRpVx = (sp._ckRpVx || 0) * 0.6 + dx * 0.4; sp._ckRpVy = (sp._ckRpVy || 0) * 0.6 + dy * 0.4;
      const vx = sp._ckRpVx, vy = sp._ckRpVy, ax = Math.abs(vx), ay = Math.abs(vy), mueve = ax + ay > 0.15;
      if (mueve) sp._ckRpQuieto = now;
      // caminando
      if (k === F.lado || k === F.wf || k === F.we) {
        if (!mueve) return;
        let q = k;
        if (ay > ax * (k === F.lado ? 1.25 : 0.8)) q = vy > 0 ? F.wf : F.we; else q = F.lado;
        if (q !== k) {
          if (q === F.lado) { if (sp._ckRpFlip !== undefined) sp.setFlipX(vx < 0 ? true : vx > 0 ? false : sp._ckRpFlip); }
          else { if (k === F.lado) sp._ckRpFlip = sp.flipX; sp.setFlipX(false); }
          tocar(sp, q);
        }
        sp._ckRpDir = q === F.wf ? 'abajo' : q === F.we ? 'arriba' : 'lado';
        return;
      }
      // se paró: mirando para donde iba
      if (k === F.quieto && !mueve && (sp._ckRpDir === 'abajo' || sp._ckRpDir === 'arriba')) {
        tocar(sp, sp._ckRpDir === 'abajo' ? F.f : F.e); sp.setFlipX(false); sp._ckRpDir = null; return;
      }
      if ((k === F.f || k === F.e) && mueve) { sp._ckRpDir = null; }
      // las torpezas del Rey, de vez en cuando
      if ((k === F.quieto || k === F.f || k === F.e) && F.gracias.length && !mueve && !S.dialogOpen && sp.visible && sp.alpha > 0.5 && now - (sp._ckRpQuieto || 0) > 1200 &&
          Phaser.Geom.Rectangle.Contains(vista, sp.x, sp.y)) {
        if (!sp._ckRpGracia) sp._ckRpGracia = now + 4000 + Math.random() * 6000;
        else if (now > sp._ckRpGracia) { sp._ckRpGracia = now + 10000 + Math.random() * 8000; hacer(S, sp); }
      }
    });
  };
  const u0 = P.update;
  P.update = function () {
    const r = u0 ? u0.apply(this, arguments) : undefined;
    try { if (this.children && this.cameras && this.cameras.main) mirar(this); } catch (e) {}
    return r;
  };
  window.CK_REY_POSES = { hacer, FAM, ARTE: Object.keys(ARTE) };
})();
